<?php $e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');$payload=[];foreach($packages as $p){$p['category_ids']=$categoryMap[(int)$p['id']]??[];$p['bouquet_ids']=$bouquetMap[(int)$p['id']]??[];$payload[]=$p;}?>
<div x-data="packagesPage(<?=htmlspecialchars(json_encode($payload,JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_QUOT),ENT_QUOTES)?>)" class="space-y-6"><div class="flex justify-between"><div><h1 class="text-3xl font-bold">Packages</h1><p class="text-slate-400">Bouquets de canales, películas y series para cuentas y revendedores.</p></div><button @click="create()" class="bg-cyan-600 px-4 py-2 rounded">Crear package</button></div>
<section class="grid md:grid-cols-2 xl:grid-cols-3 gap-4"><?php foreach($packages as $p):?><article class="bg-slate-900 border <?=$p['active']?'border-slate-800':'border-amber-900'?> rounded-xl p-5"><div class="flex justify-between"><div><h2 class="text-xl font-bold"><?=$e($p['name'])?></h2><p class="text-sm text-slate-400"><?=$e($p['description']??'Sin descripción')?></p></div><span class="text-xs <?=$p['active']?'text-emerald-400':'text-amber-400'?>"><?=$p['active']?'Activo':'Inactivo'?></span></div><div class="grid grid-cols-3 gap-2 my-5 text-center"><div class="bg-slate-800 rounded p-2"><strong><?=$p['duration_days']?:'∞'?></strong><div class="text-xs text-slate-500">días</div></div><div class="bg-slate-800 rounded p-2"><strong><?=number_format((int)$p['credit_cost'])?></strong><div class="text-xs text-slate-500">créditos</div></div><div class="bg-slate-800 rounded p-2"><strong><?=$p['max_connections']?></strong><div class="text-xs text-slate-500">conexiones</div></div></div><div class="text-xs text-slate-400 min-h-10"><?=$e($p['category_names']??'Sin categorías')?></div><div class="grid grid-cols-4 gap-2 mt-4 text-center text-xs"><span><?=$p['categories_count']?> categorías</span><span><?=$p['items_count']?> directos</span><span><?=$p['accounts_count']?> cuentas</span><span><?=$p['resellers_count']?> resellers</span></div><div class="flex gap-2 mt-4"><button @click="edit(<?=$p['id']?>)" class="flex-1 bg-indigo-700 py-2 rounded">Editar</button><form method="post" action="/packages/toggle"><?=$csrf->field()?><input type="hidden" name="id" value="<?=$p['id']?>"><button class="bg-slate-700 px-4 py-2 rounded"><?=$p['active']?'Desactivar':'Activar'?></button></form></div></article><?php endforeach?><?php if(!$packages):?><p class="text-slate-500">No hay packages creados.</p><?php endif?></section>
<div x-show="open" x-cloak style="display:none" class="relative bg-black/75 z-50 grid place-items-center p-4" @click.self="open=false"><form method="post" action="/packages" class="bg-slate-900 border border-slate-700 rounded-2xl p-6 max-w-4xl w-full max-h-[92vh] overflow-y-auto"><?=$csrf->field()?><input type="hidden" name="id" :value="form.id"><div class="flex justify-between"><h2 class="text-2xl font-bold" x-text="form.id?'Editar package':'Nuevo package'"></h2><button type="button" @click="open=false">✕</button></div><div class="grid md:grid-cols-2 gap-4 mt-5"><label>Nombre<input required name="name" x-model="form.name" class="w-full bg-slate-800 p-2 rounded"></label><label>Descripción<input name="description" x-model="form.description" class="w-full bg-slate-800 p-2 rounded"></label><label>Duración en días<input type="number" min="0" max="3650" name="duration_days" x-model="form.duration_days" class="w-full bg-slate-800 p-2 rounded"><span class="text-xs text-slate-500">0 significa sin expiración fija.</span></label><label>Coste en créditos<input type="number" min="0" name="credit_cost" x-model="form.credit_cost" class="w-full bg-slate-800 p-2 rounded"></label><label>Conexiones máximas sugeridas<input type="number" min="1" max="100" name="max_connections" x-model="form.max_connections" class="w-full bg-slate-800 p-2 rounded"></label><div class="flex flex-wrap gap-5 items-center"><label><input type="checkbox" name="active" x-model="form.active"> Activo</label><label><input type="checkbox" name="reseller_enabled" x-model="form.reseller_enabled"> Disponible para revendedores</label><label><input type="checkbox" name="is_trial" x-model="form.is_trial"> Trial</label></div></div><h3 class="font-bold mt-6">Bouquets incluidos</h3><p class="text-sm text-slate-400">El contenido nuevo que llegue a estas categorías se añade automáticamente al acceso del package.</p><div class="grid md:grid-cols-3 gap-4 mt-3"><?php foreach(['live'=>'Canales en vivo','movie'=>'Películas','series'=>'Series'] as $type=>$label):?><fieldset class="bg-slate-800/60 rounded-xl p-4"><legend class="font-bold px-2"><?=$label?></legend><div class="space-y-2 max-h-64 overflow-y-auto"><?php foreach($categories as $c):if($c['type']!==$type)continue;?><label class="flex gap-2 items-start"><input type="checkbox" name="category_ids[]" value="<?=$c['id']?>" :checked="form.category_ids.includes(<?=$c['id']?>)"><span><?=$e($c['name'])?> <small class="text-slate-500">(<?=$c['items_count']?>)</small></span></label><?php endforeach?></div></fieldset><?php endforeach?></div><div class="flex justify-end gap-3 mt-6"><button type="button" @click="open=false" class="bg-slate-700 px-5 py-2 rounded">Cancelar</button><button class="bg-emerald-700 px-5 py-2 rounded">Guardar package</button></div></form></div></div>
<script>function packagesPage(items){return{items,open:false,form:{},create(){this.form={id:'',name:'',description:'',duration_days:30,credit_cost:0,max_connections:1,active:true,reseller_enabled:true,is_trial:false,category_ids:[]};this.open=true},edit(id){let p=this.items.find(x=>Number(x.id)===id);this.form={...p,active:Boolean(Number(p.active)),reseller_enabled:Boolean(Number(p.reseller_enabled)),is_trial:Boolean(Number(p.is_trial)),category_ids:(p.category_ids||[]).map(Number)};this.open=true}}}</script>
